    },
    {
      "slot": "C2",
      "old": "血梅香每跳额外 +生命值上限×10%；Q 安神秘法命中亦施加血梅香",
      "new": "血梅香每跳 +生命值上限 ?%；血梅香造成的伤害 +?%",
      "unit": "生命上限%",
