{"description":"校验 JSON 并统计条数","command":"$p='./'
try {
  $raw = Get-Content -Raw -Encoding UTF8 $p
  $o = $raw | ConvertFrom-Json
  "CHECK1: OK"
  "char=$($o.char) name_zh=$($o.name_zh)"
  "changes=$($o.changes.Count) unknowns=$($o.unknowns.Count) sources=$($o.sources.Count)"
  "slots=" + (($o.changes | ForEach-Object { $_.slot }) -join ',')
  "confs=" + (($o.changes | ForEach-Object { $_.conf }) -join ',')
  "source_types=" + (($o.sources | ForEach-Object { $_.type }) -join ',')
} catch {
  "CHECK1: FAIL -> " + $_.Exception.Message
}"}

