{"description":"剥两行后二次校验并回显证据行","command":"$p='./'
$txt=[System.IO.File]::ReadAllText($p,(New-Object System.Text.UTF8Encoding($false)))
$lines=$txt -split "`r`n"
"total_lines=$($lines.Count)"
"last1=[$($lines[-1])]"
"last2=[$($lines[-2])]"
"last3=[$($lines[-3])]"
$body = ($lines[0..($lines.Count-3)] -join "`n")
try {
  $o = $body | ConvertFrom-Json
  "CHECK2: OK"
  "changes=$($o.changes.Count) unknowns=$($o.unknowns.Count) sources=$($o.sources.Count)"
} catch {
  "CHECK2: FAIL -> " + $_.Exception.Message
}
"bom_check_first_bytes=" + (((Get-Content -Path $p -Encoding Byte -TotalCount 3) | ForEach-Object { $_.ToString('X2') }) -join ' ')"}

