content.arguments:
{"description":"终校验并列出全部来源地址","command":"$p='./'
$bytes=[System.IO.File]::ReadAllBytes($p)
$txt=[System.Text.Encoding]::UTF8.GetString($bytes)
$lines=@($txt -split "`n" | ForEach-Object{$_.TrimEnd("`r")})
$idx=-1; for($i=$lines.Count-1;$i -ge 0;$i--){ if($lines[$i].Trim() -ne ''){$idx=$i;break} }
"last_nonempty=[$($lines[$idx])]"
"blank_before_it=" + ($lines[$idx-1].Trim() -eq '')
$bodyText=($lines[0..($idx-2)] -join "`n").TrimEnd()
try { $o=$bodyText|ConvertFrom-Json; "CHECK2(final): OK"; "changes=$($o.changes.Count) unknowns=$($o.unknowns.Count) sources=$($o.sources.Count)"; $i=0; foreach($s in $o.sources){ $i++; "  $i. [$($s.type)|$($s.time)] $($s.url)" } } catch { "CHECK2: FAIL -> "+$_.Exception.Message }
"final_bytes=$((Get-Item $p).Length)"; "final_sha256_12=$((Get-FileHash $p -Algorithm SHA256).Hash.Substring(0,12).ToLower())""}

